@charset "UTF-8";
/* =========================================================
   CW_MONITOREO
   ========================================================= */
#cw-monitoring {
  --cw-bg: #f7fbff;
  --cw-surface: #ffffff;
  --cw-surface-soft: #f7faff;
  --cw-ink: #101d35;
  --cw-ink-2: #32445f;
  --cw-muted: #73839a;
  --cw-line: #dce7f3;
  --cw-line-strong: #c8daeb;
  --cw-blue: #1473e6;
  --cw-blue-2: #258cf4;
  --cw-blue-soft: #eaf4ff;
  --cw-cyan: #18c7df;
  --cw-cyan-soft: #e5fbff;
  --cw-purple: #7657ee;
  --cw-purple-soft: #f0edff;
  --cw-green: #0fb981;
  --cw-green-soft: #e8fbf4;
  --cw-red: #f24f67;
  --cw-red-soft: #fff0f3;
  --cw-orange: #f2a93b;
  --cw-orange-soft: #fff6e7;
  --cw-shadow:
    0 12px 34px rgba(34, 85, 133, 0.055);
  --cw-radius: 18px;
  width: 100%;
  color: var(--cw-ink);
  font-family: Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: radial-gradient(circle at 85% 0%, rgba(24, 199, 223, 0.035), transparent 28%), radial-gradient(circle at 3% 0%, rgba(20, 115, 230, 0.04), transparent 25%), var(--cw-bg);
  border-radius: 18px;
}

#cw-monitoring *,
#cw-monitoring *::before,
#cw-monitoring *::after {
  box-sizing: border-box;
}

#cw-monitoring button,
#cw-monitoring select {
  font: inherit;
}

#cw-monitoring button {
  border: 0;
}

#cw-monitoring .cw-shell {
  width: 100%;
  padding: 22px;
}

/* =========================================================
   HEADER
   ========================================================= */
#cw-monitoring .cw-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
}

#cw-monitoring .cw-title-block {
  min-width: 260px;
}

#cw-monitoring .cw-eyebrow {
  margin-bottom: 7px;
  color: var(--cw-blue);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.16em;
}

#cw-monitoring .cw-title {
  margin: 0;
  color: var(--cw-ink);
  font-size: clamp(24px, 2vw, 34px);
  line-height: 1.05;
  font-weight: 780;
  letter-spacing: -0.035em;
}

#cw-monitoring .cw-subtitle {
  margin: 7px 0 0;
  color: var(--cw-muted);
  font-size: 13px;
  line-height: 1.45;
}

#cw-monitoring .cw-toolbar {
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
}

#cw-monitoring .cw-control {
  min-width: 150px;
}

#cw-monitoring .cw-control-target {
  min-width: 200px;
}

#cw-monitoring .cw-control-label {
  display: block;
  margin: 0 0 5px 7px;
  color: #6f7f94;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.025em;
}

#cw-monitoring .cw-control-field {
  height: 48px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid var(--cw-line-strong);
  border-radius: 13px;
  box-shadow: 0 6px 18px rgba(27, 80, 124, 0.03);
}

#cw-monitoring .cw-control-icon {
  color: var(--cw-blue);
  font-size: 14px;
  line-height: 1;
}

#cw-monitoring .cw-select {
  width: 100%;
  color: var(--cw-ink);
  background: transparent;
  border: 0;
  outline: none;
  font-size: 12px;
  font-weight: 650;
  cursor: pointer;
}

#cw-monitoring .cw-updated {
  height: 48px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 8px 0 5px;
}

#cw-monitoring .cw-status-dot {
  width: 10px;
  height: 10px;
  flex: 0 0 auto;
  background: var(--cw-green);
  border-radius: 50%;
  box-shadow: 0 0 0 5px rgba(15, 185, 129, 0.08);
}

#cw-monitoring .cw-updated-label {
  color: var(--cw-muted);
  font-size: 10px;
  line-height: 1.25;
}

#cw-monitoring .cw-updated-value {
  margin-top: 2px;
  color: var(--cw-ink-2);
  font-size: 10px;
  font-weight: 650;
  line-height: 1.25;
}

#cw-monitoring .cw-refresh {
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  color: var(--cw-blue);
  background: var(--cw-blue-soft);
  border: 1px solid #d4e8fb;
  border-radius: 14px;
  font-size: 24px;
  cursor: pointer;
  transition: transform 0.2s ease, background 0.2s ease;
}

#cw-monitoring .cw-refresh:hover {
  background: #dceeff;
  transform: rotate(12deg);
}

/* =========================================================
   PANELS
   ========================================================= */
#cw-monitoring .cw-panel {
  min-width: 0;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(255, 255, 255, 0.97));
  border: 1px solid var(--cw-line-strong);
  border-radius: var(--cw-radius);
  box-shadow: var(--cw-shadow);
  overflow: hidden;
}

#cw-monitoring .cw-panel-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 20px 10px;
}

#cw-monitoring .cw-panel-title {
  margin: 0;
  color: var(--cw-ink);
  font-size: 16px;
  line-height: 1.2;
  font-weight: 780;
  letter-spacing: -0.02em;
}

#cw-monitoring .cw-panel-subtitle {
  margin: 4px 0 0;
  color: var(--cw-muted);
  font-size: 11px;
  line-height: 1.35;
}

/* =========================================================
   HERO
   ========================================================= */
#cw-monitoring .cw-hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 2.2fr) minmax(300px, 0.95fr);
  gap: 12px;
}

#cw-monitoring .cw-pulse-panel {
  position: relative;
}

#cw-monitoring .cw-segmented {
  display: inline-flex;
  gap: 3px;
  padding: 4px;
  background: #f1f6fb;
  border: 1px solid #e0eaf4;
  border-radius: 12px;
}

#cw-monitoring .cw-segmented button {
  padding: 8px 12px;
  color: #536985;
  background: transparent;
  border-radius: 9px;
  font-size: 10px;
  font-weight: 650;
  cursor: pointer;
  transition: color 0.2s ease, background 0.2s ease, box-shadow 0.2s ease;
}

#cw-monitoring .cw-segmented button.active {
  color: #ffffff;
  background: linear-gradient(135deg, var(--cw-blue), var(--cw-blue-2));
  box-shadow: 0 5px 12px rgba(20, 115, 230, 0.22);
}

#cw-monitoring .cw-chart-legend {
  min-height: 24px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 15px;
  padding: 0 20px;
}

#cw-monitoring .cw-legend-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #536985;
  font-size: 10px;
  font-weight: 650;
}

#cw-monitoring .cw-legend-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

#cw-monitoring .cw-chart {
  position: relative;
  width: 100%;
  min-height: 285px;
  padding: 2px 14px 12px;
}

#cw-monitoring .cw-chart svg {
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
}

#cw-monitoring .cw-chart-tooltip {
  position: absolute;
  z-index: 10;
  min-width: 150px;
  padding: 10px 12px;
  color: var(--cw-ink);
  background: rgba(255, 255, 255, 0.97);
  border: 1px solid #dce7f1;
  border-radius: 12px;
  box-shadow: 0 14px 35px rgba(31, 71, 112, 0.14);
  pointer-events: none;
  transform: translate(-50%, -110%);
  opacity: 0;
  transition: opacity 0.12s ease;
}

#cw-monitoring .cw-chart-tooltip.visible {
  opacity: 1;
}

#cw-monitoring .cw-tooltip-date {
  margin-bottom: 6px;
  color: var(--cw-muted);
  font-size: 10px;
  font-weight: 700;
}

#cw-monitoring .cw-tooltip-row {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  margin: 4px 0;
  font-size: 10px;
}

#cw-monitoring .cw-tooltip-row strong {
  color: var(--cw-ink);
  font-weight: 750;
}

/* =========================================================
   SUMMARY
   ========================================================= */
#cw-monitoring .cw-summary-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  padding: 5px 18px 2px;
}

#cw-monitoring .cw-stat {
  min-width: 0;
  padding: 18px 14px;
  border-bottom: 1px solid #edf2f7;
}

#cw-monitoring .cw-stat:nth-child(odd) {
  border-right: 1px solid #edf2f7;
}

#cw-monitoring .cw-stat:nth-last-child(-n+2) {
  border-bottom: 0;
}

#cw-monitoring .cw-stat-label {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #58708c;
  font-size: 10px;
  font-weight: 680;
}

#cw-monitoring .cw-stat-icon {
  width: 25px;
  height: 25px;
  display: grid;
  place-items: center;
  color: var(--cw-blue);
  background: var(--cw-blue-soft);
  border-radius: 8px;
  font-size: 12px;
  font-weight: 900;
}

#cw-monitoring .cw-stat-value {
  margin-top: 12px;
  color: var(--cw-ink);
  font-size: clamp(22px, 2.1vw, 34px);
  line-height: 1;
  font-weight: 780;
  letter-spacing: -0.04em;
}

#cw-monitoring .cw-stat-helper {
  margin-top: 7px;
  color: var(--cw-muted);
  font-size: 9px;
  line-height: 1.3;
}

#cw-monitoring .cw-coverage-summary {
  margin: 6px 18px 16px;
  padding: 12px 14px;
  background: linear-gradient(90deg, #f6fbff, #f9fdff);
  border: 1px solid #e2edf6;
  border-radius: 12px;
}

#cw-monitoring .cw-coverage-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: #536985;
  font-size: 10px;
  font-weight: 650;
}

#cw-monitoring .cw-coverage-row strong {
  color: var(--cw-ink);
}

#cw-monitoring .cw-progress {
  height: 5px;
  margin-top: 9px;
  background: #e6eef6;
  border-radius: 99px;
  overflow: hidden;
}

#cw-monitoring .cw-progress > span {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, var(--cw-blue), var(--cw-cyan));
  border-radius: inherit;
}

/* =========================================================
   PLATFORM CARDS
   ========================================================= */
#cw-monitoring .cw-platform-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 10px;
  margin-top: 12px;
}

#cw-monitoring .cw-platform-card {
  min-width: 0;
  padding: 14px 16px 13px;
  background: rgba(255, 255, 255, 0.97);
  border: 1px solid var(--cw-line-strong);
  border-radius: 15px;
  box-shadow: 0 8px 24px rgba(34, 85, 133, 0.04);
}

#cw-monitoring .cw-platform-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}

#cw-monitoring .cw-platform-name {
  display: flex;
  align-items: center;
  gap: 9px;
  color: var(--cw-ink);
  font-size: 12px;
  font-weight: 760;
}

#cw-monitoring .cw-platform-badge {
  width: 29px;
  height: 29px;
  display: grid;
  place-items: center;
  color: #ffffff;
  border-radius: 9px;
  font-size: 13px;
  font-weight: 850;
}

#cw-monitoring .platform-facebook {
  background: linear-gradient(135deg, #1877f2, #0b5fcc);
}

#cw-monitoring .platform-instagram {
  background: linear-gradient(135deg, #7f5af0, #d84ca2);
}

#cw-monitoring .platform-threads {
  background: linear-gradient(135deg, #151a22, #384151);
}

#cw-monitoring .cw-spark {
  width: 116px;
  height: 34px;
}

#cw-monitoring .cw-platform-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0;
}

#cw-monitoring .cw-platform-metric {
  min-width: 0;
  padding: 2px 10px;
  border-left: 1px solid #edf2f7;
}

#cw-monitoring .cw-platform-metric:first-child {
  padding-left: 0;
  border-left: 0;
}

#cw-monitoring .cw-platform-metric-value {
  color: var(--cw-ink);
  font-size: 14px;
  line-height: 1.1;
  font-weight: 780;
}

#cw-monitoring .cw-platform-metric-label {
  margin-top: 5px;
  color: var(--cw-muted);
  font-size: 8px;
  line-height: 1.2;
}

/* =========================================================
   LOWER GRID
   ========================================================= */
#cw-monitoring .cw-lower-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr) minmax(0, 0.85fr);
  gap: 12px;
  margin-top: 12px;
}

#cw-monitoring .cw-list-panel {
  min-height: 380px;
}

#cw-monitoring .cw-link-button {
  flex: 0 0 auto;
  padding: 7px 11px;
  color: var(--cw-blue);
  background: #ffffff;
  border: 1px solid #d8e8f7 !important;
  border-radius: 10px;
  font-size: 9px;
  font-weight: 750;
  cursor: pointer;
  transition: background 0.18s ease, border-color 0.18s ease, transform 0.18s ease;
}

#cw-monitoring .cw-link-button:hover {
  background: var(--cw-blue-soft);
  border-color: #bad9f5 !important;
  transform: translateY(-1px);
}

/* =========================================================
   GENERIC LISTS
   ========================================================= */
#cw-monitoring .cw-list {
  padding: 0 18px 12px;
}

#cw-monitoring .cw-list-item {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-height: 72px;
  padding: 10px 0;
  border-bottom: 1px solid #edf2f7;
}

#cw-monitoring .cw-list-item:last-child {
  border-bottom: 0;
}

#cw-monitoring .cw-rank {
  width: 19px;
  color: #8aa0b7;
  text-align: center;
  font-size: 10px;
  font-weight: 800;
}

#cw-monitoring .cw-thumb {
  width: 54px;
  height: 54px;
  display: grid;
  place-items: center;
  overflow: hidden;
  color: #ffffff;
  background: linear-gradient(145deg, #0f6fde, #21c5da);
  border-radius: 9px;
  font-size: 18px;
  font-weight: 800;
}

#cw-monitoring .cw-post-main {
  min-width: 0;
}

#cw-monitoring .cw-post-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  margin-bottom: 4px;
  color: #71849a;
  font-size: 8px;
  font-weight: 650;
}

#cw-monitoring .cw-post-title {
  max-width: 100%;
  color: var(--cw-ink);
  font-size: 10px;
  line-height: 1.35;
  font-weight: 730;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

#cw-monitoring .cw-post-metrics {
  display: flex;
  align-items: center;
  gap: 11px;
  flex-wrap: wrap;
  margin-top: 7px;
  color: #71849a;
  font-size: 8px;
  font-weight: 620;
}

#cw-monitoring .cw-impact {
  min-width: 48px;
  text-align: center;
}

#cw-monitoring .cw-impact-value {
  color: var(--cw-ink);
  font-size: 13px;
  line-height: 1;
  font-weight: 800;
}

#cw-monitoring .cw-impact-label {
  margin-top: 4px;
  color: var(--cw-muted);
  font-size: 7px;
}

#cw-monitoring .cw-impact-bar {
  width: 48px;
  height: 4px;
  margin: 7px auto 0;
  background: #e8eef5;
  border-radius: 99px;
  overflow: hidden;
}

#cw-monitoring .cw-impact-bar span {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, var(--cw-blue), var(--cw-cyan));
  border-radius: inherit;
}

#cw-monitoring .cw-open-post {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  color: var(--cw-blue);
  background: transparent;
  border-radius: 9px;
  font-size: 15px;
  cursor: pointer;
  transition: background 0.18s ease, transform 0.18s ease;
}

#cw-monitoring .cw-open-post:hover {
  background: var(--cw-blue-soft);
  transform: translateY(-1px);
}

#cw-monitoring .cw-score-note {
  padding: 2px 20px 15px;
  color: #8b9caf;
  font-size: 8px;
  line-height: 1.4;
}

/* =========================================================
   TOP POSTS — PREMIUM STREAM
   ========================================================= */
#cw-monitoring #topPostsList {
  padding: 2px 18px 8px;
}

#cw-monitoring .cw-top-post-item {
  position: relative;
  display: grid;
  grid-template-columns: 28px 48px minmax(0, 1fr) 82px;
  align-items: center;
  column-gap: 12px;
  min-height: 82px;
  padding: 11px 6px;
  border-bottom: 1px solid #eaf0f6;
  transition: background 0.18s ease, transform 0.18s ease;
}

#cw-monitoring .cw-top-post-item:last-child {
  border-bottom: 0;
}

#cw-monitoring .cw-top-post-item:hover {
  background: linear-gradient(90deg, rgba(234, 244, 255, 0.48), rgba(229, 251, 255, 0.18), transparent 92%);
}

#cw-monitoring .cw-top-post-rank {
  width: 24px;
  height: 24px;
  display: grid;
  place-items: center;
  color: #59708c;
  background: #f4f8fc;
  border: 1px solid #e3ecf5;
  border-radius: 8px;
  font-size: 9px;
  font-weight: 820;
}

#cw-monitoring .cw-top-post-item:nth-child(1) .cw-top-post-rank {
  color: #ffffff;
  background: linear-gradient(135deg, #1473e6, #18bfe0);
  border-color: transparent;
  box-shadow: 0 5px 14px rgba(20, 115, 230, 0.18);
}

#cw-monitoring .cw-top-post-item:nth-child(2) .cw-top-post-rank {
  color: #536985;
  background: linear-gradient(135deg, #eef4fa, #dfe9f3);
}

#cw-monitoring .cw-top-post-item:nth-child(3) .cw-top-post-rank {
  color: #85611b;
  background: linear-gradient(135deg, #fff6e6, #f9e7c5);
  border-color: #f3dfb8;
}

#cw-monitoring .cw-top-platform {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  color: #ffffff;
  border-radius: 13px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.2), 0 6px 14px rgba(28, 73, 116, 0.08);
  font-size: 14px;
  font-weight: 820;
}

#cw-monitoring .cw-top-post-main {
  min-width: 0;
}

#cw-monitoring .cw-top-post-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  margin-bottom: 5px;
  color: #72849a;
  font-size: 8.5px;
  line-height: 1.2;
  font-weight: 650;
}

#cw-monitoring .cw-top-platform-name {
  color: #43617f;
  font-weight: 760;
}

#cw-monitoring .cw-top-meta-separator {
  color: #b2c0ce;
}

#cw-monitoring .cw-top-post-title {
  max-width: 100%;
  color: #14223a;
  font-size: 10.5px;
  line-height: 1.38;
  font-weight: 720;
  letter-spacing: -0.008em;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

#cw-monitoring .cw-top-post-metrics {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-top: 7px;
  color: #6c8097;
  font-size: 8.5px;
  line-height: 1;
  font-weight: 640;
}

#cw-monitoring .cw-top-metric {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  white-space: nowrap;
}

#cw-monitoring .cw-top-metric-icon {
  color: #7596b8;
  font-size: 9px;
}

#cw-monitoring .cw-top-side {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 7px;
}

#cw-monitoring .cw-impact-ring {
  --impact-pct: 0;
  position: relative;
  width: 49px;
  height: 49px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 50%;
  background: conic-gradient(from -90deg, var(--cw-blue) calc(var(--impact-pct) * 1%), #e6edf5 calc(var(--impact-pct) * 1%));
