/* =========================================================
   CW_MONITOREO
   ========================================================= */

const CW = {
  model: {},
  filters: {
    range: "30d",
    platform: "all",
    targetId: null
  },
  metric: "posts",
  expanded: {
    top: false,
    signals: false,
    recent: false
  },
  resizeTimer: null,
  colors: {
    facebook: "#1473e6",
    instagram: "#7657ee",
    threads: "#8fa4ba"
  }
};

/* =========================================================
   HELPERS
   ========================================================= */

function num(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}
function arr(value) {
  return Array.isArray(value) ? value : [];
}
function escapeHtml(value) {
  return String(value ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#039;");
}
function truncate(value, max = 120) {
  const text = String(value ?? "").trim();
  if (text.length <= max) {
    return text;
  }
  return text.slice(0, max - 1).trim() + "…";
}
function normalizePlatform(value) {
  const p = String(value ?? "").trim().toLowerCase();
  if (p.includes("facebook")) {
    return "facebook";
  }
  if (p.includes("instagram")) {
    return "instagram";
  }
  if (p.includes("thread")) {
    return "threads";
  }
  return p || "unknown";
}
function platformLabel(value) {
  const p = normalizePlatform(value);
  if (p === "facebook") {
    return "Facebook";
  }
  if (p === "instagram") {
    return "Instagram";
  }
  if (p === "threads") {
    return "Threads";
  }
  return p ? p.charAt(0).toUpperCase() + p.slice(1) : "Desconocida";
}
function platformInitial(value) {
  const p = normalizePlatform(value);
  if (p === "facebook") {
    return "f";
  }
  if (p === "instagram") {
    return "IG";
  }
  if (p === "threads") {
    return "@";
  }
  return "•";
}
function formatNumber(value) {
  return new Intl.NumberFormat("es-MX", {
    maximumFractionDigits: 0
  }).format(num(value));
}
function formatCompact(value) {
  const n = num(value);
  if (Math.abs(n) < 1000) {
    return formatNumber(n);
  }
  return new Intl.NumberFormat("es-MX", {
    notation: "compact",
    maximumFractionDigits: 1
  }).format(n);
}
function formatDate(value) {
  if (!value) {
    return "—";
  }
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) {
    return "—";
  }
  return new Intl.DateTimeFormat("es-MX", {
    day: "2-digit",
    month: "short",
    year: "numeric"
  }).format(d);
}
function formatDateTime(value) {
  if (!value) {
    return "—";
  }
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) {
    return "—";
  }
  return new Intl.DateTimeFormat("es-MX", {
    day: "2-digit",
    month: "short",
    hour: "2-digit",
    minute: "2-digit"
  }).format(d);
}
function safeDate(value) {
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d;
}
function getRangeDays(range) {
  const match = String(range ?? "").match(/^(\d+)d$/);
  return match ? Number(match[1]) : 30;
}
function getRangeBounds() {
  const days = getRangeDays(CW.filters.range);
  const to = new Date();
  const from = new Date(to.getTime() - days * 24 * 60 * 60 * 1000);
  return {
    from,
    to
  };
}
function isInsideCurrentRange(value) {
  if (!value) {
    return true;
  }
  const d = safeDate(value);
  if (!d) {
    return true;
  }
  const {
    from,
    to
  } = getRangeBounds();
  return d.getTime() >= from.getTime() && d.getTime() <= to.getTime();
}
function overviewRowInRange(row) {
  const first = safeDate(row.first_post_at);
  const last = safeDate(row.last_post_at);
  if (!first && !last) {
    return true;
  }
  const {
    from,
    to
  } = getRangeBounds();
  const firstTime = first ? first.getTime() : -Infinity;
  const lastTime = last ? last.getTime() : Infinity;
  return lastTime >= from.getTime() && firstTime <= to.getTime();
}
function matchesPlatform(row) {
  if (CW.filters.platform === "all") {
    return true;
  }
  return normalizePlatform(row.platform) === CW.filters.platform;
}
function totalInteractions(row) {
  return num(row.likes) + num(row.comments_reported ?? row.comments) + num(row.shares) + num(row.reposts) + num(row.quotes);
}
function getOverview() {
  return arr(CW.model.overview).filter(overviewRowInRange).filter(matchesPlatform);
}
function getTimeline() {
  return arr(CW.model.timeline).filter(row => {
    const date = row.day ?? row.date ?? row.published_date ?? row.published_at;
    return isInsideCurrentRange(date);
  }).filter(matchesPlatform);
}
function getTopPosts() {
  return arr(CW.model.topPosts).filter(row => {
    const date = row.published_at ?? row.created_at;
    return isInsideCurrentRange(date);
  }).filter(matchesPlatform);
}
function getAlerts() {
  return arr(CW.model.alerts).filter(row => {
    const date = row.alert_created_at ?? row.created_at ?? row.comment_published_at ?? row.published_at;
    return isInsideCurrentRange(date);
  }).filter(matchesPlatform);
}
function getRecentPosts() {
  return arr(CW.model.recentPosts).filter(row => {
    const date = row.published_at ?? row.created_at;
    return isInsideCurrentRange(date);
  }).filter(matchesPlatform);
}
function getLatestTimestamp() {
  const values = [];
  getOverview().forEach(row => {
    if (row.last_post_at) {
      values.push(row.last_post_at);
    }
  });
  getTimeline().forEach(row => {
    const date = row.day ?? row.date ?? row.published_at;
    if (date) {
      values.push(date);
    }
  });
  const valid = values.map(value => safeDate(value)).filter(Boolean).sort((a, b) => b.getTime() - a.getTime());
  return valid[0] ?? null;
}
function scoreForPost(row) {
  if (row.impact_score !== undefined && row.impact_score !== null) {
    return num(row.impact_score);
  }
  return num(row.likes) + num(row.comments ?? row.comments_reported) * 2 + num(row.shares) * 3 + num(row.reposts) * 3 + num(row.quotes) * 3;
}

/* =========================================================
   FILTER CONTROLS
   ========================================================= */

function renderControls() {
  const period = document.getElementById("filterPeriod");
  const platform = document.getElementById("filterPlatform");
  const target = document.getElementById("filterTarget");
  const ranges = arr(CW.model.filterOptions?.ranges).length ? arr(CW.model.filterOptions.ranges) : ["7d", "15d", "30d"];
  period.innerHTML = ranges.map(range => {
    const days = getRangeDays(range);
    return `
          <option
            value="${escapeHtml(range)}"
          >
            Últimos ${days} días
          </option>
        `;
  }).join("");
  period.value = CW.filters.range;
  const platforms = arr(CW.model.filterOptions?.platforms).length ? arr(CW.model.filterOptions.platforms) : ["all", "facebook", "instagram", "threads"];
  platform.innerHTML = platforms.map(p => {
    const label = p === "all" ? "Todas" : platformLabel(p);
    return `
          <option
            value="${escapeHtml(p)}"
          >
            ${escapeHtml(label)}
          </option>
        `;
  }).join("");
  platform.value = CW.filters.platform;
  const targets = arr(CW.model.targets);
  if (targets.length) {
    target.innerHTML = targets.map(item => {
      const id = item.id ?? item.target_id ?? "";
      const label = item.name ?? item.handle ?? item.label ?? "Target";
      return `
            <option
              value="${escapeHtml(id)}"
            >
              ${escapeHtml(label)}
            </option>
          `;
    }).join("");
    if (CW.filters.targetId) {
      target.value = CW.filters.targetId;
    }
  } else {
    target.innerHTML = `
      <option value="">
        ${escapeHtml(CW.model.targetName || CW.model.queryName || "Consulta seleccionada")}
      </option>
    `;
  }
  period.onchange = () => {
    updateFilters({
      range: period.value
    });
  };
  platform.onchange = () => {
    updateFilters({
      platform: platform.value
    });
  };
  target.onchange = () => {
    updateFilters({
      targetId: target.value || null
    });
  };
}
function updateFilters(patch) {
  CW.filters = {
    ...CW.filters,
    ...patch
  };
  appsmith.updateModel({
    filters: CW.filters
  });
  try {
    appsmith.triggerEvent("onFilterChange", {
      filters: CW.filters
    });
  } catch (_) {

    /* Event may not yet be configured */
  }
  render();
}

/* =========================================================
   HEADER
   ========================================================= */

function renderHeader() {
  const latest = getLatestTimestamp();
  document.getElementById("lastUpdated").textContent = latest ? formatDateTime(latest) : "Sin datos";
  const days = getRangeDays(CW.filters.range);
  document.getElementById("periodSummaryLabel").textContent = `Totales registrados en los últimos ${days} días.`;
}

/* =========================================================
   SUMMARY
   ========================================================= */

function renderSummary() {
  const rows = getOverview();
  const totals = rows.reduce((acc, row) => {
    acc.posts += num(row.posts);
    acc.postsWithMetrics += num(row.posts_with_metrics);
    acc.likes += num(row.likes);
    acc.comments += num(row.comments_reported);
    acc.shares += num(row.shares);
    acc.reposts += num(row.reposts);
    acc.quotes += num(row.quotes);
    acc.views += num(row.views);
    return acc;
  }, {
    posts: 0,
    postsWithMetrics: 0,
    likes: 0,
    comments: 0,
    shares: 0,
    reposts: 0,
    quotes: 0,
    views: 0
  });
  const interactions = totals.likes + totals.comments + totals.shares + totals.reposts + totals.quotes;
  const coverage = totals.posts > 0 ? totals.postsWithMetrics / totals.posts * 100 : 0;
  const stats = [{
    icon: "▣",
    label: "Publicaciones",
    value: formatNumber(totals.posts),
    helper: "posts en el período"
  }, {
    icon: "↗",
    label: "Interacciones",
    value: formatNumber(interactions),
    helper: "likes, comentarios y compartidos"
  }, {
    icon: "○",
    label: "Comentarios",
    value: formatNumber(totals.comments),
    helper: "comentarios reportados"
  }, {
    icon: "▶",
    label: "Visualizaciones",
    value: formatNumber(totals.views),
    helper: "visualizaciones registradas"
  }];
  document.getElementById("summaryGrid").innerHTML = stats.map(stat => `
        <div class="cw-stat">

          <div class="cw-stat-label">

            <span class="cw-stat-icon">
              ${stat.icon}
            </span>

            ${escapeHtml(stat.label)}

          </div>

          <div class="cw-stat-value">
            ${escapeHtml(stat.value)}
          </div>

          <div class="cw-stat-helper">
            ${escapeHtml(stat.helper)}
          </div>

        </div>
      `).join("");
  document.getElementById("coverageSummary").innerHTML = `
    <div class="cw-coverage-row">

      <span>
        Cobertura de métricas
      </span>

      <strong>
        ${coverage.toFixed(1)}%
      </strong>

    </div>

    <div class="cw-progress">

      <span
        style="
          width:
          ${Math.max(0, Math.min(100, coverage))}%;
        "
      >
      </span>

    </div>
  `;
}

/* =========================================================
   TIMELINE / CHART
   ========================================================= */

function metricValue(row) {
  if (CW.metric === "posts") {
    return num(row.posts);
  }
  if (CW.metric === "comments") {
    return num(row.comments ?? row.comments_reported);
  }
  if (CW.metric === "views") {
    return num(row.views);
  }
  return num(row.likes) + num(row.comments ?? row.comments_reported) + num(row.shares) + num(row.reposts) + num(row.quotes);
}
function makeSmoothPath(points) {
  if (!points.length) {
    return "";
  }
  if (points.length === 1) {
    return `M ${points[0][0]} ` + `${points[0][1]}`;
  }
  let d = `M ${points[0][0]} ` + `${points[0][1]}`;
  for (let i = 1; i < points.length; i++) {
    const previous = points[i - 1];
    const current = points[i];
    const middleX = (previous[0] + current[0]) / 2;
    d += ` C ${middleX} ` + `${previous[1]},` + ` ${middleX} ` + `${current[1]},` + ` ${current[0]} ` + `${current[1]}`;
  }
  return d;
}
function niceMax(value) {
  if (value <= 0) {
    return 10;
  }
  const power = Math.pow(10, Math.floor(Math.log10(value)));
  return Math.ceil(value / power) * power;
}
function renderChartLegend(platforms) {
  document.getElementById("chartLegend").innerHTML = platforms.map(platform => `
        <span class="cw-legend-item">

          <span
            class="cw-legend-dot"
            style="
              background:
              ${CW.colors[platform] || "#90a4b8"};
            "
          >
          </span>

          ${escapeHtml(platformLabel(platform))}

        </span>
      `).join("");
}
function renderPulseChart() {
  const container = document.getElementById("pulseChart");
  const rows = getTimeline();
  if (!rows.length) {
    container.innerHTML = emptyState("∿", "No existen datos de evolución para el período seleccionado.");
    renderChartLegend([]);
    return;
  }
  const byDate = new Map();
  rows.forEach(row => {
    const rawDate = row.day ?? row.date ?? row.published_date ?? row.published_at;
    if (!rawDate) {
      return;
    }
    const d = safeDate(rawDate);
    if (!d) {
      return;
    }
    const dateKey = d.toISOString().slice(0, 10);
    const platform = normalizePlatform(row.platform);
    if (!byDate.has(dateKey)) {
      byDate.set(dateKey, {});
    }
    const dateBucket = byDate.get(dateKey);
    dateBucket[platform] = (dateBucket[platform] || 0) + metricValue(row);
  });
  const dates = Array.from(byDate.keys()).sort();
  const platformSet = new Set();
  rows.forEach(row => {
    platformSet.add(normalizePlatform(row.platform));
  });
  const preferredOrder = ["facebook", "instagram", "threads"];
  const platforms = preferredOrder.filter(platform => platformSet.has(platform));
  renderChartLegend(platforms);
  const width = 1000;
  const height = 285;
  const margin = {
    top: 15,
    right: 16,
    bottom: 38,
    left: 52
  };
  const plotWidth = width - margin.left - margin.right;
  const plotHeight = height - margin.top - margin.bottom;
  let maxValue = 0;
  dates.forEach(date => {
    platforms.forEach(platform => {
      maxValue = Math.max(maxValue, num(byDate.get(date)[platform]));
    });
  });
  const yMax = niceMax(maxValue * 1.08);
  const xFor = index => {
    if (dates.length <= 1) {
      return margin.left;
    }
    return margin.left + index / (dates.length - 1) * plotWidth;
  };
  const yFor = value => margin.top + plotHeight - num(value) / yMax * plotHeight;
  const yTicks = [0, 0.25, 0.5, 0.75, 1];
  const gridLines = yTicks.map(ratio => {
    const y = margin.top + plotHeight - ratio * plotHeight;
    const value = yMax * ratio;
    return `
          <line
            x1="${margin.left}"
            x2="${width - margin.right}"
            y1="${y}"
            y2="${y}"
            stroke="#e8f0f7"
            stroke-width="1"
          />

          <text
            x="${margin.left - 10}"
            y="${y + 3}"
            text-anchor="end"
            fill="#8293a8"
            font-size="9"
          >
            ${escapeHtml(formatCompact(value))}
          </text>
        `;
  }).join("");
  let seriesSvg = "";
  platforms.forEach((platform, seriesIndex) => {
    const points = dates.map((date, index) => [xFor(index), yFor(byDate.get(date)[platform] || 0)]);
    const line = makeSmoothPath(points);
    const area = `${line} ` + `L ${xFor(dates.length - 1)} ` + `${margin.top + plotHeight} ` + `L ${xFor(0)} ` + `${margin.top + plotHeight} Z`;
    const color = CW.colors[platform] || "#90a4b8";
    seriesSvg += `
        <defs>

          <linearGradient
            id="gradient-${platform}"
            x1="0"
            y1="0"
            x2="0"
            y2="1"
          >

            <stop
              offset="0%"
              stop-color="${color}"
              stop-opacity="${seriesIndex === 0 ? 0.27 : 0.20}"
            />

            <stop
              offset="100%"
              stop-color="${color}"
              stop-opacity="0.015"
            />

          </linearGradient>

        </defs>

        <path
          d="${area}"
          fill="url(#gradient-${platform})"
        />

        <path
          d="${line}"
          fill="none"
          stroke="${color}"
          stroke-width="${seriesIndex === 0 ? 2.4 : 2}"
          stroke-linecap="round"
          stroke-linejoin="round"
        />

        ${points.map(point => `
              <circle
                cx="${point[0]}"
                cy="${point[1]}"
                r="2.1"
                fill="${color}"
              />
            `).join("")}
      `;
  });
  const xLabelIndexes = Array.from(new Set([0, Math.floor((dates.length - 1) * 0.2), Math.floor((dates.length - 1) * 0.4), Math.floor((dates.length - 1) * 0.6), Math.floor((dates.length - 1) * 0.8), dates.length - 1]));
  const xLabels = xLabelIndexes.map(index => `
        <text
          x="${xFor(index)}"
          y="${height - 11}"
          text-anchor="middle"
          fill="#8293a8"
          font-size="9"
        >
          ${escapeHtml(new Intl.DateTimeFormat("es-MX", {
    day: "2-digit",
    month: "short"
  }).format(new Date(`${dates[index]}T12:00:00`)))}
        </text>
      `).join("");
  container.innerHTML = `
    <svg
      viewBox="
        0 0
        ${width}
        ${height}
      "
      preserveAspectRatio="none"
      role="img"
      aria-label="Evolución temporal"
    >

      ${gridLines}

      ${seriesSvg}

      ${xLabels}

      <line
        id="cwHoverLine"
        x1="0"
        x2="0"
        y1="${margin.top}"
        y2="${margin.top + plotHeight}"
        stroke="#73aef0"
        stroke-width="1"
        stroke-dasharray="3 4"
        opacity="0"
      />

      <rect
        id="cwChartHitbox"
        x="${margin.left}"
        y="${margin.top}"
        width="${plotWidth}"
        height="${plotHeight}"
        fill="transparent"
      />

    </svg>

    <div
      id="cwChartTooltip"
      class="cw-chart-tooltip"
    >
    </div>
  `;
  const svg = container.querySelector("svg");
  const hitbox = document.getElementById("cwChartHitbox");
  const hoverLine = document.getElementById("cwHoverLine");
  const tooltip = document.getElementById("cwChartTooltip");
  hitbox.addEventListener("mousemove", event => {
    const rect = svg.getBoundingClientRect();
    const mouseSvgX = (event.clientX - rect.left) / rect.width * width;
    const ratio = Math.max(0, Math.min(1, (mouseSvgX - margin.left) / plotWidth));
    const index = Math.round(ratio * (dates.length - 1));
    const x = xFor(index);
    hoverLine.setAttribute("x1", x);
    hoverLine.setAttribute("x2", x);
    hoverLine.setAttribute("opacity", "1");
    const date = dates[index];
    const bucket = byDate.get(date);
    const rowsHtml = platforms.map(platform => `
            <div class="cw-tooltip-row">

              <span>
                ${escapeHtml(platformLabel(platform))}
              </span>

              <strong>
                ${escapeHtml(formatNumber(bucket[platform] || 0))}
              </strong>

            </div>
          `).join("");
    tooltip.innerHTML = `
        <div class="cw-tooltip-date">
          ${escapeHtml(formatDate(`${date}T12:00:00`))}
        </div>

        ${rowsHtml}
      `;
    tooltip.style.left = `${x / width * 100}%`;
    tooltip.style.top = `${margin.top / height * 100 + 17}%`;
    tooltip.classList.add("visible");
  });
  hitbox.addEventListener("mouseleave", () => {
    hoverLine.setAttribute("opacity", "0");
    tooltip.classList.remove("visible");
  });
}

/* =========================================================
   PLATFORM CARDS
   ========================================================= */

function getPlatformTimeline(platform) {
  return getTimeline().filter(row => normalizePlatform(row.platform) === platform).sort((a, b) => {
    const aDate = safeDate(a.day ?? a.date ?? a.published_at);
    const bDate = safeDate(b.day ?? b.date ?? b.published_at);
    return (aDate?.getTime() || 0) - (bDate?.getTime() || 0);
  });
}
function sparklineSvg(platform) {
  const rows = getPlatformTimeline(platform);
  if (!rows.length) {
    return "";
  }
  const values = rows.map(metricValue);
  const max = Math.max(...values, 1);
  const width = 116;
  const height = 34;
  const points = values.map((value, index) => {
    const x = values.length <= 1 ? 0 : index / (values.length - 1) * width;
    const y = height - value / max * (height - 5);
    return [x, y];
  });
  const path = makeSmoothPath(points);
  const color = CW.colors[platform] || "#1473e6";
  return `
    <svg
      class="cw-spark"
      viewBox="
        0 0
        ${width}
        ${height}
      "
      preserveAspectRatio="none"
      aria-hidden="true"
    >

      <path
        d="${path}"
        fill="none"
        stroke="${color}"
        stroke-width="2"
        stroke-linecap="round"
      />

    </svg>
  `;
}
function renderPlatforms() {
  const rows = getOverview();
  const container = document.getElementById("platformGrid");
  if (!rows.length) {
    container.innerHTML = "";
    return;
  }
  container.innerHTML = rows.map(row => {
    const platform = normalizePlatform(row.platform);
    const interactions = totalInteractions(row);
    return `
          <article
            class="cw-platform-card"
          >

            <div
              class="
                cw-platform-card-head
              "
            >

              <div
                class="
                  cw-platform-name
                "
              >

                <span
                  class="
                    cw-platform-badge
                    platform-${platform}
                  "
                >
                  ${escapeHtml(platformInitial(platform))}
                </span>

                ${escapeHtml(platformLabel(platform))}

              </div>

              ${sparklineSvg(platform)}

            </div>

            <div
              class="
                cw-platform-metrics
              "
            >

              ${platformMetric(row.posts, "publicaciones")}

              ${platformMetric(interactions, "interacciones")}

              ${platformMetric(row.comments_reported, "comentarios")}

              ${platformMetric(row.views, "visualizaciones")}

            </div>

          </article>
        `;
  }).join("");
}
function platformMetric(value, label) {
  return `
    <div
      class="
        cw-platform-metric
      "
    >

      <div
        class="
          cw-platform-metric-value
        "
      >
        ${escapeHtml(formatCompact(value))}
      </div>

      <div
        class="
          cw-platform-metric-label
        "
      >
        ${escapeHtml(label)}
      </div>

    </div>
  `;
}

/* =========================================================
   TOP POSTS
   ========================================================= */

function renderTopPosts() {
  const container = document.getElementById("topPostsList");
  const rows = getTopPosts().sort((a, b) => scoreForPost(b) - scoreForPost(a));
  if (!rows.length) {
    container.innerHTML = emptyState("★", "No existen publicaciones de impacto para el período seleccionado.");
    return;
  }
  const visible = CW.expanded.top ? rows.slice(0, 20) : rows.slice(0, 4);
  const maxScore = Math.max(...rows.map(scoreForPost), 1);
  container.innerHTML = visible.map((row, index) => {
    const platform = normalizePlatform(row.platform);
    const score = scoreForPost(row);
    const relative = Math.max(1, Math.min(100, Math.round(score / maxScore * 100)));
    const content = row.content_text ?? row.post_content ?? row.caption ?? "Publicación sin texto disponible";
    const date = row.published_at ?? row.created_at;
    const comments = row.comments ?? row.comments_reported;
    return `
            <div
              class="
                cw-top-post-item
              "
            >

              <div
                class="
                  cw-top-post-rank
                "
              >
                ${index + 1}
              </div>


              <div
                class="
                  cw-top-platform
                  platform-${platform}
                "
                title="${escapeHtml(platformLabel(platform))}"
              >
                ${escapeHtml(platformInitial(platform))}
              </div>


              <div
                class="
                  cw-top-post-main
                "
              >

                <div
                  class="
                    cw-top-post-meta
                  "
                >

                  <span
                    class="
                      cw-top-platform-name
                    "
                  >
                    ${escapeHtml(platformLabel(platform))}
                  </span>

                  <span
                    class="
                      cw-top-meta-separator
                    "
                  >
                    •
                  </span>

                  <span>
                    ${escapeHtml(formatDate(date))}
                  </span>

                  ${row.post_type ? `
                        <span
                          class="
                            cw-top-meta-separator
                          "
                        >
                          •
                        </span>

                        <span>
                          ${escapeHtml(row.post_type)}
                        </span>
                      ` : ""}

                </div>


                <div
                  class="
                    cw-top-post-title
                  "
                >
                  ${escapeHtml(truncate(content, 135))}
                </div>


                <div
                  class="
                    cw-top-post-metrics
                  "
                >

                  <span
                    class="
                      cw-top-metric
                    "
                    title="Likes"
                  >
                    <span
                      class="
                        cw-top-metric-icon
                      "
                    >
                      ♥
                    </span>

                    ${escapeHtml(formatCompact(row.likes))}
                  </span>


                  <span
                    class="
                      cw-top-metric
                    "
                    title="Comentarios"
                  >
                    <span
                      class="
                        cw-top-metric-icon
                      "
                    >
                      ◯
                    </span>

                    ${escapeHtml(formatCompact(comments))}
                  </span>


                  <span
                    class="
                      cw-top-metric
                    "
                    title="Compartidos"
                  >
                    <span
                      class="
                        cw-top-metric-icon
                      "
                    >
                      ↗
                    </span>

                    ${escapeHtml(formatCompact(row.shares))}
                  </span>


                  <span
                    class="
                      cw-top-metric
                    "
                    title="Visualizaciones"
                  >
                    <span
                      class="
                        cw-top-metric-icon
                      "
                    >
                      ◉
                    </span>

                    ${escapeHtml(formatCompact(row.views))}
                  </span>

                </div>

              </div>


              <div
                class="
                  cw-top-side
                "
              >

                <div
                  class="
                    cw-impact-ring
                  "
                  style="
                    --impact-pct:
                    ${relative};
                  "
                  title="
                    Impacto relativo
                    ${relative}/100
                  "
                >

                  <div
                    class="
                      cw-impact-ring-inner
                    "
                  >

                    <div
                      class="
                        cw-impact-ring-value
                      "
                    >
                      ${relative}
                    </div>

                    <div
                      class="
                        cw-impact-ring-label
                      "
                    >
                      relativo
                    </div>

                  </div>

                </div>


                ${row.post_url ? `
                      <button
                        type="button"
                        class="
                          cw-top-open
                        "
                        data-post-index="
                          ${index}
                        "
                        title="
                          Abrir publicación
                        "
                      >
                        ↗
                      </button>
                    ` : ""}

              </div>

            </div>
          `;
  }).join("");
  container.querySelectorAll("[data-post-index]").forEach(button => {
    button.onclick = () => {
      const index = Number(button.dataset.postIndex);
      const row = visible[index];
      openPost(row);
    };
  });
  document.getElementById("toggleTopPosts").textContent = CW.expanded.top ? "Ver menos" : "Ver todas";
}

/* =========================================================
   SIGNALS
   ========================================================= */

function signalTone(type) {
  const text = String(type ?? "").toLowerCase();
  if (text.includes("negative") || text.includes("negativ") || text.includes("critical") || text.includes("crít")) {
    return "signal-red";
  }
  if (text.includes("warning") || text.includes("alert") || text.includes("volume") || text.includes("spike")) {
    return "signal-orange";
  }
  if (text.includes("positive") || text.includes("positiv")) {
    return "signal-green";
  }
  return "";
}
function renderSignals() {
  const rows = getAlerts().sort((a, b) => {
    const ad = safeDate(a.alert_created_at ?? a.created_at);
    const bd = safeDate(b.alert_created_at ?? b.created_at);
    return (bd?.getTime() || 0) - (ad?.getTime() || 0);
  });
  const totalAlerts = getOverview().reduce((sum, row) => sum + num(row.alerts), 0);
  document.getElementById("signalStats").innerHTML = `
    <span class="cw-chip">

      Señales registradas

      <strong>
        ${formatNumber(totalAlerts)}
      </strong>

    </span>

    ${rows.length ? `
          <span class="cw-chip">

            Detalle cargado

            <strong>
              ${formatNumber(rows.length)}
            </strong>

          </span>
        ` : ""}
  `;
  const container = document.getElementById("signalsList");
  if (!rows.length) {
    container.innerHTML = emptyState("◎", "El período contiene alertas, pero todavía no existe detalle de señales conectado al modelo.");
    return;
  }
  const visible = CW.expanded.signals ? rows.slice(0, 30) : rows.slice(0, 4);
  container.innerHTML = visible.map((row, index) => {
    const type = row.alert_type ?? row.type ?? "Señal";
    const content = row.content_text ?? row.comment_text ?? row.post_content_text ?? "Señal registrada";
    const author = row.author_name ?? row.author_username ?? row.handle ?? "";
    const date = row.alert_created_at ?? row.created_at ?? row.comment_published_at;
    return `
            <div
              class="
                cw-signal-item
              "
            >

              <div
                class="
                  cw-signal-accent
                  ${signalTone(type)}
                "
              >
              </div>


              <div>

                <span
                  class="
                    cw-signal-type
                  "
                >
                  ${escapeHtml(type)}
                </span>


                <div
                  class="
                    cw-signal-title
                  "
                >
                  ${escapeHtml(truncate(content, 115))}
                </div>


                <div
                  class="
                    cw-signal-meta
                  "
                >

                  ${author ? `${escapeHtml(author)} · ` : ""}

                  ${escapeHtml(formatDateTime(date))}

                  ${row.likes_count !== undefined ? ` · ${formatCompact(row.likes_count)} likes` : ""}

                </div>

              </div>


              ${row.post_url ? `
                    <button
                      type="button"
                      class="
                        cw-open-post
                      "
                      data-signal-index="
                        ${index}
                      "
                    >
                      ↗
                    </button>
                  ` : ""}

            </div>
          `;
  }).join("");
  container.querySelectorAll("[data-signal-index]").forEach(button => {
    button.onclick = () => {
      const index = Number(button.dataset.signalIndex);
      openPost(visible[index]);
    };
  });
  document.getElementById("toggleSignals").textContent = CW.expanded.signals ? "Ver menos" : "Ver todas";
}

/* =========================================================
   RECENT POSTS
   ========================================================= */

function renderRecentPosts() {
  const rows = getRecentPosts().sort((a, b) => {
    const ad = safeDate(a.published_at);
    const bd = safeDate(b.published_at);
    return (bd?.getTime() || 0) - (ad?.getTime() || 0);
  });
  const container = document.getElementById("recentPostsList");
  if (!rows.length) {
    container.innerHTML = emptyState("↻", "Todavía no existe detalle de publicaciones recientes conectado al modelo.");
    return;
  }
  const visible = CW.expanded.recent ? rows.slice(0, 30) : rows.slice(0, 4);
  container.innerHTML = visible.map((row, index) => {
    const platform = normalizePlatform(row.platform);
    const content = row.content_text ?? "Publicación sin texto disponible";
    return `
            <div
              class="
                cw-list-item
              "
            >

              <div
                class="
                  cw-thumb
                  platform-${platform}
                "
              >
                ${escapeHtml(platformInitial(platform))}
              </div>


              <div
                class="
                  cw-post-main
                "
              >

                <div
                  class="
                    cw-post-meta
                  "
                >

                  <span>
                    ${escapeHtml(platformLabel(platform))}
                  </span>

                  <span>
                    ·
                  </span>

                  <span>
                    ${escapeHtml(formatDateTime(row.published_at))}
                  </span>

                </div>


                <div
                  class="
                    cw-post-title
                  "
                >
                  ${escapeHtml(truncate(content, 100))}
                </div>


                <div
                  class="
                    cw-post-metrics
                  "
                >

                  <span>
                    ♥
                    ${formatCompact(row.likes)}
                  </span>

                  <span>
                    ◯
                    ${formatCompact(row.comments ?? row.comments_reported)}
                  </span>

                  <span>
                    ↗
                    ${formatCompact(row.shares)}
                  </span>

                  <span>
                    ◉
                    ${formatCompact(row.views)}
                  </span>

                </div>

              </div>


              ${row.post_url ? `
                    <button
                      type="button"
                      class="
                        cw-open-post
                      "
                      data-recent-index="
                        ${index}
                      "
                    >
                      ↗
                    </button>
                  ` : ""}

            </div>
          `;
  }).join("");
  container.querySelectorAll("[data-recent-index]").forEach(button => {
    button.onclick = () => {
      const index = Number(button.dataset.recentIndex);
      openPost(visible[index]);
    };
  });
  document.getElementById("toggleRecent").textContent = CW.expanded.recent ? "Ver menos" : "Ver todas";
}

/* =========================================================
   OPEN POST
   ========================================================= */

function openPost(row) {
  if (!row) {
    return;
  }
  appsmith.updateModel({
    selectedPost: row
  });
  try {
    appsmith.triggerEvent("onOpenPost", {
      post: row
    });
  } catch (_) {

    /* Event may not yet be configured */
  }
}

/* =========================================================
   EMPTY STATE
   ========================================================= */

function emptyState(symbol, text) {
  return `
    <div class="cw-empty">

      <div
        class="
          cw-empty-inner
        "
      >

        <div
          class="
            cw-empty-symbol
          "
        >
          ${escapeHtml(symbol)}
        </div>

        ${escapeHtml(text)}

      </div>

    </div>
  `;
}

/* =========================================================
   BUTTONS
   ========================================================= */

function bindButtons() {
  document.getElementById("refreshButton").onclick = () => {
    try {
      appsmith.triggerEvent("onRefresh");
    } catch (_) {
      render();
    }
  };
  document.getElementById("toggleTopPosts").onclick = () => {
    CW.expanded.top = !CW.expanded.top;
    renderTopPosts();
  };
  document.getElementById("toggleSignals").onclick = () => {
    CW.expanded.signals = !CW.expanded.signals;
    renderSignals();
  };
  document.getElementById("toggleRecent").onclick = () => {
    CW.expanded.recent = !CW.expanded.recent;
    renderRecentPosts();
  };
  document.querySelectorAll("#metricTabs button").forEach(button => {
    button.onclick = () => {
      CW.metric = button.dataset.metric;
      document.querySelectorAll("#metricTabs button").forEach(item => {
        item.classList.toggle("active", item === button);
      });
      renderPulseChart();
      renderPlatforms();
    };
  });
}

/* =========================================================
   RENDER
   ========================================================= */

function render() {
  renderControls();
  renderHeader();
  renderSummary();
  renderPulseChart();
  renderPlatforms();
  renderTopPosts();
  renderSignals();
  renderRecentPosts();
  bindButtons();
}

/* =========================================================
   INITIALIZATION
   ========================================================= */

appsmith.onReady(() => {
  CW.model = appsmith.model || {};
  CW.filters = {
    ...CW.filters,
    ...(CW.model.filters || {})
  };
  render();
  appsmith.onModelChange(newModel => {
    CW.model = newModel || {};
    if (newModel?.filters) {
      CW.filters = {
        ...CW.filters,
        ...newModel.filters
      };
    }
    render();
  });
  appsmith.onUiChange(() => {
    clearTimeout(CW.resizeTimer);
    CW.resizeTimer = setTimeout(() => {
      renderPulseChart();
      renderPlatforms();
    }, 120);
  });
});

