  background: var(--cw-blue-soft);

  border-radius: 12px;

  font-size: 18px;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1320px) {

  #cw-monitoring .cw-header {
    align-items: flex-start;

    flex-direction: column;
  }

  #cw-monitoring .cw-toolbar {
    width: 100%;

    justify-content: flex-start;
  }

  #cw-monitoring .cw-lower-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  #cw-monitoring .cw-lower-grid > :last-child {
    grid-column: span 2;
  }

}


@media (max-width: 1000px) {

  #cw-monitoring .cw-hero-grid {
    grid-template-columns: 1fr;
  }

  #cw-monitoring .cw-summary-grid {
    grid-template-columns:
      repeat(4, minmax(0, 1fr));
