    height: 44px;
  }

}


@media (max-width: 520px) {

  #cw-monitoring .cw-toolbar {
    grid-template-columns: 1fr;
  }

  #cw-monitoring .cw-refresh {
    width: 100%;
  }

  #cw-monitoring .cw-list-item {
    grid-template-columns:
      auto
      minmax(0, 1fr);
  }

  #cw-monitoring .cw-impact {
    display: none;
  }

  #cw-monitoring .cw-top-post-item {
    grid-template-columns:
      25px
      42px
      minmax(0, 1fr);

    align-items: start;
  }

  #cw-monitoring .cw-top-platform {
    width: 42px;
    height: 42px;
  }

  #cw-monitoring .cw-top-side {
    grid-column:
      2 / 4;

    justify-content: flex-start;

    padding-top: 5px;
  }

  #cw-monitoring .cw-impact-ring {
    width: 42px;
    height: 42px;
  }

}

