/* =========================================================
   CW_MONITOREO
   ========================================================= */

const CW = {
  model: {},

  filters: {
    range: "30d",
    platform: "all",
    targetId: null
  },

  metric: "posts",

  expanded: {
    top: false,
    signals: false,
    recent: false
  },

  resizeTimer: null,

  colors: {
    facebook: "#1473e6",
    instagram: "#7657ee",
    threads: "#8fa4ba"
  }
};


/* =========================================================
   HELPERS
   ========================================================= */

function num(value) {
  const parsed = Number(value);

  return Number.isFinite(parsed)
    ? parsed
    : 0;
}


function arr(value) {
  return Array.isArray(value)
    ? value
    : [];
}


function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}


function truncate(value, max = 120) {
  const text =
    String(value ?? "").trim();

  if (text.length <= max) {
    return text;
  }

  return (
    text
      .slice(0, max - 1)
      .trim() +
    "…"
  );
}


function normalizePlatform(value) {
  const p =
    String(value ?? "")
      .trim()
      .toLowerCase();

  if (p.includes("facebook")) {
    return "facebook";
  }

  if (p.includes("instagram")) {
    return "instagram";
  }

  if (p.includes("thread")) {
    return "threads";
  }

  return p || "unknown";
}


function platformLabel(value) {
  const p =
    normalizePlatform(value);

  if (p === "facebook") {
    return "Facebook";
  }

  if (p === "instagram") {
    return "Instagram";
  }

  if (p === "threads") {
    return "Threads";
  }

  return p
    ? p.charAt(0).toUpperCase() +
        p.slice(1)
    : "Desconocida";
}


function platformInitial(value) {
  const p =
    normalizePlatform(value);

  if (p === "facebook") {
    return "f";
  }

  if (p === "instagram") {
    return "IG";
  }

  if (p === "threads") {
    return "@";
  }

  return "•";
}


function formatNumber(value) {
  return new Intl.NumberFormat(
    "es-MX",
    {
      maximumFractionDigits: 0
    }
  ).format(num(value));
}


function formatCompact(value) {
  const n =
    num(value);

  if (Math.abs(n) < 1000) {
    return formatNumber(n);
  }

  return new Intl.NumberFormat(
    "es-MX",
    {
      notation: "compact",
      maximumFractionDigits: 1
    }
  ).format(n);
}


function formatDate(value) {
  if (!value) {
    return "—";
  }

  const d =
    new Date(value);

  if (Number.isNaN(d.getTime())) {
    return "—";
  }

  return new Intl.DateTimeFormat(
    "es-MX",
    {
      day: "2-digit",
      month: "short",
      year: "numeric"
    }
  ).format(d);
}


function formatDateTime(value) {
  if (!value) {
    return "—";
  }

  const d =
    new Date(value);

  if (Number.isNaN(d.getTime())) {
    return "—";
  }

  return new Intl.DateTimeFormat(
    "es-MX",
    {
      day: "2-digit",
      month: "short",
      hour: "2-digit",
      minute: "2-digit"
    }
  ).format(d);
}


function safeDate(value) {
  const d =
    new Date(value);

  return Number.isNaN(d.getTime())
    ? null
    : d;
}


function getRangeDays(range) {
  const match =
    String(range ?? "")
      .match(/^(\d+)d$/);

  return match
    ? Number(match[1])
    : 30;
}


function getRangeBounds() {
  const days =
    getRangeDays(
      CW.filters.range
    );

  const to =
    new Date();

  const from =
    new Date(
      to.getTime() -
      days *
      24 *
      60 *
      60 *
      1000
    );

  return {
    from,
    to
  };
}


function isInsideCurrentRange(value) {
  if (!value) {
    return true;
  }

  const d =
    safeDate(value);

  if (!d) {
    return true;
  }

  const {
    from,
    to
  } = getRangeBounds();

  return (
    d.getTime() >=
      from.getTime() &&
    d.getTime() <=
      to.getTime()
  );
}


function overviewRowInRange(row) {
  const first =
    safeDate(
      row.first_post_at
    );

  const last =
    safeDate(
      row.last_post_at
    );

  if (!first && !last) {
    return true;
  }

  const {
    from,
    to
  } = getRangeBounds();

  const firstTime =
    first
      ? first.getTime()
      : -Infinity;

  const lastTime =
    last
      ? last.getTime()
      : Infinity;

  return (
    lastTime >=
      from.getTime() &&
    firstTime <=
      to.getTime()
  );
}


function matchesPlatform(row) {
  if (
    CW.filters.platform ===
    "all"
  ) {
    return true;
  }

  return (
    normalizePlatform(
      row.platform
    ) ===
    CW.filters.platform
  );
}


function totalInteractions(row) {
  return (
    num(row.likes) +
    num(
      row.comments_reported ??
      row.comments
    ) +
    num(row.shares) +
    num(row.reposts) +
    num(row.quotes)
  );
}


function getOverview() {
  return arr(
    CW.model.overview
  )
    .filter(
      overviewRowInRange
    )
    .filter(
      matchesPlatform
    );
}


function getTimeline() {
  return arr(
    CW.model.timeline
  )
    .filter(row => {
      const date =
        row.day ??
        row.date ??
        row.published_date ??
        row.published_at;

      return isInsideCurrentRange(
        date
      );
    })
    .filter(
      matchesPlatform
    );
}


function getTopPosts() {
  return arr(
    CW.model.topPosts
  )
    .filter(row => {
      const date =
        row.published_at ??
        row.created_at;

      return isInsideCurrentRange(
        date
      );
    })
    .filter(
      matchesPlatform
    );
}


function getAlerts() {
  return arr(
    CW.model.alerts
  )
    .filter(row => {
      const date =
        row.alert_created_at ??
        row.created_at ??
        row.comment_published_at ??
        row.published_at;

      return isInsideCurrentRange(
        date
      );
    })
    .filter(
      matchesPlatform
    );
}


function getRecentPosts() {
  return arr(
    CW.model.recentPosts
  )
    .filter(row => {
      const date =
        row.published_at ??
        row.created_at;

      return isInsideCurrentRange(
        date
      );
    })
    .filter(
      matchesPlatform
    );
}


function getLatestTimestamp() {
  const values = [];

  getOverview()
    .forEach(row => {

      if (row.last_post_at) {
        values.push(
          row.last_post_at
        );
      }

    });


  getTimeline()
    .forEach(row => {

      const date =
        row.day ??
        row.date ??
        row.published_at;

      if (date) {
        values.push(date);
      }

    });


  const valid =
    values
      .map(value =>
        safeDate(value)
      )
      .filter(Boolean)
      .sort(
        (a, b) =>
          b.getTime() -
          a.getTime()
      );

  return (
    valid[0] ??
    null
  );
}


function scoreForPost(row) {
  if (
    row.impact_score !==
      undefined &&
    row.impact_score !==
      null
  ) {
    return num(
      row.impact_score
    );
  }

  return (
    num(row.likes) +
    num(
      row.comments ??
      row.comments_reported
    ) * 2 +
    num(row.shares) * 3 +
    num(row.reposts) * 3 +
    num(row.quotes) * 3
  );
}


/* =========================================================
   FILTER CONTROLS
   ========================================================= */

function renderControls() {
  const period =
    document.getElementById(
      "filterPeriod"
    );

  const platform =
    document.getElementById(
      "filterPlatform"
    );

  const target =
    document.getElementById(
      "filterTarget"
    );


  const ranges =
    arr(
      CW.model
        .filterOptions
        ?.ranges
    ).length

      ? arr(
          CW.model
            .filterOptions
            .ranges
        )

      : [
          "7d",
          "15d",
          "30d"
        ];


  period.innerHTML =
    ranges
      .map(range => {

        const days =
          getRangeDays(range);

        return `
          <option
            value="${escapeHtml(
              range
            )}"
          >
            Últimos ${days} días
          </option>
        `;

      })
      .join("");


  period.value =
    CW.filters.range;


  const platforms =
    arr(
      CW.model
        .filterOptions
        ?.platforms
    ).length

      ? arr(
          CW.model
            .filterOptions
            .platforms
        )

      : [
          "all",
          "facebook",
          "instagram",
          "threads"
        ];


  platform.innerHTML =
    platforms
      .map(p => {

        const label =
          p === "all"
            ? "Todas"
            : platformLabel(p);

        return `
          <option
            value="${escapeHtml(
              p
            )}"
          >
            ${escapeHtml(
              label
            )}
          </option>
        `;

      })
      .join("");


  platform.value =
    CW.filters.platform;


  const targets =
    arr(
      CW.model.targets
    );


  if (targets.length) {

    target.innerHTML =
      targets
        .map(item => {

          const id =
            item.id ??
            item.target_id ??
            "";

          const label =
            item.name ??
            item.handle ??
            item.label ??
            "Target";

          return `
            <option
              value="${escapeHtml(
                id
              )}"
            >
              ${escapeHtml(
                label
              )}
            </option>
          `;

        })
        .join("");


    if (
      CW.filters.targetId
    ) {
      target.value =
        CW.filters.targetId;
    }

  } else {

    target.innerHTML = `
      <option value="">
        ${escapeHtml(
          CW.model.targetName ||
          CW.model.queryName ||
          "Consulta seleccionada"
        )}
      </option>
    `;

  }


  period.onchange = () => {

    updateFilters({
      range:
        period.value
    });

  };


  platform.onchange = () => {

    updateFilters({
      platform:
        platform.value
    });

  };


  target.onchange = () => {

    updateFilters({
      targetId:
        target.value ||
        null
    });

  };
}


function updateFilters(patch) {
  CW.filters = {
    ...CW.filters,
    ...patch
  };


  appsmith.updateModel({
    filters:
      CW.filters
  });


  try {

    appsmith.triggerEvent(
      "onFilterChange",
      {
        filters:
          CW.filters
      }
    );

  } catch (_) {

    /* Event may not yet be configured */

  }


  render();
}


/* =========================================================
   HEADER
   ========================================================= */

function renderHeader() {
  const latest =
    getLatestTimestamp();


  document.getElementById(
    "lastUpdated"
  ).textContent =
    latest
      ? formatDateTime(
          latest
        )
      : "Sin datos";


  const days =
    getRangeDays(
      CW.filters.range
    );


  document.getElementById(
    "periodSummaryLabel"
  ).textContent =
    `Totales registrados en los últimos ${days} días.`;
}


/* =========================================================
   SUMMARY
   ========================================================= */

function renderSummary() {
  const rows =
    getOverview();


  const totals =
    rows.reduce(
      (acc, row) => {

        acc.posts +=
          num(row.posts);

        acc.postsWithMetrics +=
          num(
            row.posts_with_metrics
          );

        acc.likes +=
          num(row.likes);

        acc.comments +=
          num(
            row.comments_reported
          );

        acc.shares +=
          num(row.shares);

        acc.reposts +=
          num(row.reposts);

        acc.quotes +=
          num(row.quotes);

        acc.views +=
          num(row.views);

        return acc;
      },
      {
        posts: 0,
        postsWithMetrics: 0,
        likes: 0,
        comments: 0,
        shares: 0,
        reposts: 0,
        quotes: 0,
        views: 0
      }
    );


  const interactions =
    totals.likes +
    totals.comments +
    totals.shares +
    totals.reposts +
    totals.quotes;


  const coverage =
    totals.posts > 0

      ? (
          totals.postsWithMetrics /
          totals.posts
        ) * 100

      : 0;


  const stats = [
    {
      icon: "▣",
      label: "Publicaciones",
      value:
        formatNumber(
          totals.posts
        ),
      helper:
        "posts en el período"
    },
    {
      icon: "↗",
      label: "Interacciones",
      value:
        formatNumber(
          interactions
        ),
      helper:
        "likes, comentarios y compartidos"
    },
    {
      icon: "○",
      label: "Comentarios",
      value:
        formatNumber(
          totals.comments
        ),
      helper:
        "comentarios reportados"
    },
    {
      icon: "▶",
      label: "Visualizaciones",
      value:
        formatNumber(
          totals.views
        ),
      helper:
        "visualizaciones registradas"
    }
  ];


  document.getElementById(
    "summaryGrid"
  ).innerHTML =
    stats
      .map(stat => `
        <div class="cw-stat">

          <div class="cw-stat-label">

            <span class="cw-stat-icon">
              ${stat.icon}
            </span>

            ${escapeHtml(
              stat.label
            )}

          </div>

          <div class="cw-stat-value">
            ${escapeHtml(
              stat.value
            )}
          </div>

          <div class="cw-stat-helper">
            ${escapeHtml(
              stat.helper
            )}
          </div>

        </div>
      `)
      .join("");


  document.getElementById(
    "coverageSummary"
  ).innerHTML = `
    <div class="cw-coverage-row">

      <span>
        Cobertura de métricas
      </span>

      <strong>
        ${coverage.toFixed(1)}%
      </strong>

    </div>

    <div class="cw-progress">

      <span
        style="
          width:
          ${Math.max(
            0,
            Math.min(
              100,
              coverage
            )
          )}%;
        "
      >
      </span>

    </div>
  `;
}


/* =========================================================
   TIMELINE / CHART
   ========================================================= */

function metricValue(row) {
  if (
    CW.metric ===
    "posts"
  ) {
    return num(
      row.posts
    );
  }


  if (
    CW.metric ===
    "comments"
  ) {
    return num(
      row.comments ??
      row.comments_reported
    );
  }


  if (
    CW.metric ===
    "views"
  ) {
    return num(
      row.views
    );
  }


  return (
    num(row.likes) +
    num(
      row.comments ??
      row.comments_reported
    ) +
    num(row.shares) +
    num(row.reposts) +
    num(row.quotes)
  );
}


function makeSmoothPath(points) {
  if (!points.length) {
    return "";
  }


  if (
    points.length ===
    1
  ) {
    return (
      `M ${points[0][0]} ` +
      `${points[0][1]}`
    );
  }


  let d =
    `M ${points[0][0]} ` +
    `${points[0][1]}`;


  for (
    let i = 1;
    i < points.length;
    i++
  ) {

    const previous =
      points[i - 1];

    const current =
      points[i];

    const middleX =
      (
        previous[0] +
        current[0]
      ) / 2;


    d +=
      ` C ${middleX} ` +
      `${previous[1]},` +
      ` ${middleX} ` +
      `${current[1]},` +
      ` ${current[0]} ` +
      `${current[1]}`;

  }


  return d;
}


function niceMax(value) {
  if (value <= 0) {
    return 10;
  }


  const power =
    Math.pow(
      10,
      Math.floor(
        Math.log10(value)
      )
    );


  return (
    Math.ceil(
      value /
      power
    ) *
    power
  );
}


function renderChartLegend(
  platforms
) {
  document.getElementById(
    "chartLegend"
  ).innerHTML =
    platforms
      .map(platform => `
        <span class="cw-legend-item">

          <span
            class="cw-legend-dot"
            style="
              background:
              ${
                CW.colors[
                  platform
                ] ||
                "#90a4b8"
              };
            "
          >
          </span>

