function renderPulseChart() {
  const container =
    document.getElementById(
      "pulseChart"
    );


  const rows =
    getTimeline();


  if (!rows.length) {

    container.innerHTML =
      emptyState(
        "∿",
        "No existen datos de evolución para el período seleccionado."
      );

    renderChartLegend([]);

    return;
  }


  const byDate =
    new Map();


  rows.forEach(row => {

    const rawDate =
      row.day ??
      row.date ??
      row.published_date ??
      row.published_at;


    if (!rawDate) {
      return;
    }


    const d =
      safeDate(
        rawDate
      );


    if (!d) {
      return;
    }


    const dateKey =
      d
        .toISOString()
        .slice(0, 10);


    const platform =
      normalizePlatform(
        row.platform
      );


    if (
      !byDate.has(
        dateKey
      )
    ) {
      byDate.set(
        dateKey,
        {}
      );
    }


    const dateBucket =
      byDate.get(
        dateKey
      );


    dateBucket[
      platform
    ] =
      (
        dateBucket[
          platform
        ] ||
        0
      ) +
      metricValue(row);

  });


  const dates =
    Array
      .from(
        byDate.keys()
      )
      .sort();


  const platformSet =
    new Set();


  rows.forEach(row => {

    platformSet.add(
      normalizePlatform(
        row.platform
      )
    );

  });


  const preferredOrder = [
    "facebook",
    "instagram",
    "threads"
  ];


  const platforms =
    preferredOrder.filter(
      platform =>
        platformSet.has(
          platform
        )
    );


  renderChartLegend(
    platforms
  );


  const width =
    1000;

  const height =
    285;


  const margin = {
    top: 15,
    right: 16,
    bottom: 38,
    left: 52
  };


  const plotWidth =
    width -
    margin.left -
    margin.right;


  const plotHeight =
    height -
    margin.top -
    margin.bottom;


  let maxValue =
    0;


  dates.forEach(date => {

    platforms.forEach(
      platform => {

        maxValue =
          Math.max(
            maxValue,
            num(
              byDate.get(
                date
              )[platform]
            )
          );

      }
    );

  });


  const yMax =
    niceMax(
      maxValue *
      1.08
    );


  const xFor =
    index => {

      if (
        dates.length <=
        1
      ) {
        return margin.left;
      }

      return (
        margin.left +
        (
          index /
          (
            dates.length -
            1
          )
        ) *
        plotWidth
      );

    };


  const yFor =
    value => (
      margin.top +
      plotHeight -
      (
        num(value) /
        yMax
      ) *
      plotHeight
    );


  const yTicks = [
    0,
    0.25,
    0.5,
    0.75,
    1
  ];


  const gridLines =
    yTicks
      .map(ratio => {

        const y =
          margin.top +
          plotHeight -
          ratio *
          plotHeight;


        const value =
          yMax *
          ratio;


        return `
          <line
            x1="${margin.left}"
            x2="${width - margin.right}"
            y1="${y}"
            y2="${y}"
            stroke="#e8f0f7"
            stroke-width="1"
          />

          <text
            x="${margin.left - 10}"
            y="${y + 3}"
            text-anchor="end"
            fill="#8293a8"
            font-size="9"
          >
            ${escapeHtml(
              formatCompact(
                value
              )
            )}
          </text>
        `;

      })
      .join("");


  let seriesSvg =
    "";


  platforms.forEach(
    (
      platform,
      seriesIndex
    ) => {

      const points =
        dates.map(
          (
            date,
            index
          ) => [
            xFor(index),

            yFor(
              byDate.get(
                date
              )[platform] ||
              0
            )
          ]
        );


      const line =
        makeSmoothPath(
          points
        );


      const area =
        `${line} ` +
        `L ${xFor(
          dates.length -
          1
        )} ` +
        `${margin.top +
          plotHeight} ` +
        `L ${xFor(0)} ` +
        `${margin.top +
          plotHeight} Z`;


      const color =
        CW.colors[
          platform
        ] ||
        "#90a4b8";


      seriesSvg += `
        <defs>

          <linearGradient
            id="gradient-${platform}"
            x1="0"
            y1="0"
            x2="0"
            y2="1"
          >

            <stop
              offset="0%"
              stop-color="${color}"
              stop-opacity="${
                seriesIndex === 0
                  ? 0.27
                  : 0.20
              }"
            />

            <stop
              offset="100%"
              stop-color="${color}"
              stop-opacity="0.015"
            />

          </linearGradient>

        </defs>

        <path
          d="${area}"
          fill="url(#gradient-${platform})"
        />

        <path
          d="${line}"
          fill="none"
          stroke="${color}"
          stroke-width="${
            seriesIndex === 0
              ? 2.4
              : 2
          }"
          stroke-linecap="round"
          stroke-linejoin="round"
        />

        ${
          points
            .map(point => `
              <circle
                cx="${point[0]}"
                cy="${point[1]}"
                r="2.1"
                fill="${color}"
              />
            `)
            .join("")
        }
      `;

    }
  );


  const xLabelIndexes =
    Array.from(
      new Set([
        0,
        Math.floor(
          (
            dates.length -
            1
          ) *
          0.2
        ),
        Math.floor(
          (
            dates.length -
            1
          ) *
          0.4
        ),
        Math.floor(
          (
            dates.length -
            1
          ) *
          0.6
        ),
        Math.floor(
          (
            dates.length -
            1
          ) *
          0.8
        ),
        dates.length -
        1
      ])
    );


  const xLabels =
    xLabelIndexes
      .map(index => `
        <text
          x="${xFor(
            index
          )}"
          y="${height - 11}"
          text-anchor="middle"
          fill="#8293a8"
          font-size="9"
        >
          ${escapeHtml(
            new Intl
              .DateTimeFormat(
                "es-MX",
                {
                  day:
                    "2-digit",
                  month:
                    "short"
                }
              )
              .format(
                new Date(
                  `${dates[index]}T12:00:00`
                )
              )
          )}
        </text>
      `)
      .join("");


  container.innerHTML = `
    <svg
      viewBox="
        0 0
        ${width}
        ${height}
      "
      preserveAspectRatio="none"
      role="img"
      aria-label="Evolución temporal"
    >

      ${gridLines}

      ${seriesSvg}

      ${xLabels}

      <line
        id="cwHoverLine"
        x1="0"
        x2="0"
        y1="${margin.top}"
        y2="${
          margin.top +
          plotHeight
        }"
        stroke="#73aef0"
        stroke-width="1"
        stroke-dasharray="3 4"
        opacity="0"
      />

      <rect
        id="cwChartHitbox"
        x="${margin.left}"
        y="${margin.top}"
        width="${plotWidth}"
        height="${plotHeight}"
        fill="transparent"
      />

    </svg>

    <div
      id="cwChartTooltip"
      class="cw-chart-tooltip"
    >
    </div>
  `;


  const svg =
    container.querySelector(
      "svg"
    );


  const hitbox =
    document.getElementById(
      "cwChartHitbox"
    );


  const hoverLine =
    document.getElementById(
      "cwHoverLine"
    );


  const tooltip =
    document.getElementById(
      "cwChartTooltip"
    );


  hitbox.addEventListener(
    "mousemove",
    event => {

      const rect =
        svg
          .getBoundingClientRect();


      const mouseSvgX =
        (
          (
            event.clientX -
            rect.left
          ) /
          rect.width
        ) *
        width;


      const ratio =
        Math.max(
          0,
          Math.min(
            1,
            (
              mouseSvgX -
              margin.left
            ) /
            plotWidth
          )
        );


      const index =
        Math.round(
          ratio *
          (
            dates.length -
            1
          )
        );


      const x =
        xFor(index);


      hoverLine.setAttribute(
        "x1",
        x
      );

      hoverLine.setAttribute(
        "x2",
        x
      );

      hoverLine.setAttribute(
        "opacity",
        "1"
      );


      const date =
        dates[index];


      const bucket =
        byDate.get(
          date
        );


      const rowsHtml =
        platforms
          .map(platform => `
            <div class="cw-tooltip-row">

              <span>
                ${escapeHtml(
                  platformLabel(
                    platform
                  )
                )}
              </span>

              <strong>
                ${escapeHtml(
                  formatNumber(
                    bucket[
                      platform
                    ] ||
                    0
                  )
                )}
              </strong>

            </div>
          `)
          .join("");


      tooltip.innerHTML = `
        <div class="cw-tooltip-date">
          ${escapeHtml(
            formatDate(
              `${date}T12:00:00`
            )
          )}
        </div>

        ${rowsHtml}
      `;


      tooltip.style.left =
        `${
          (
            x /
            width
          ) *
          100
        }%`;


      tooltip.style.top =
        `${
          (
            margin.top /
            height
          ) *
          100 +
          17
        }%`;


      tooltip.classList.add(
        "visible"
      );

    }
  );


  hitbox.addEventListener(
    "mouseleave",
    () => {

      hoverLine.setAttribute(
        "opacity",
        "0"
      );

      tooltip.classList.remove(
        "visible"
      );

    }
  );
}


/* =========================================================
   PLATFORM CARDS
   ========================================================= */

function getPlatformTimeline(
  platform
) {
  return getTimeline()
    .filter(
      row =>
        normalizePlatform(
          row.platform
        ) ===
        platform
    )
    .sort(
      (a, b) => {

        const aDate =
          safeDate(
            a.day ??
            a.date ??
            a.published_at
          );


        const bDate =
          safeDate(
            b.day ??
            b.date ??
            b.published_at
          );


        return (
          (
            aDate
              ?.getTime() ||
            0
          ) -
          (
            bDate
              ?.getTime() ||
            0
          )
        );

      }
    );
}


function sparklineSvg(
  platform
) {
  const rows =
    getPlatformTimeline(
      platform
    );


  if (!rows.length) {
    return "";
  }


  const values =
    rows.map(
      metricValue
    );


  const max =
    Math.max(
      ...values,
      1
    );


  const width =
    116;

  const height =
    34;


  const points =
    values.map(
      (
        value,
        index
      ) => {

        const x =
          values.length <= 1

            ? 0

            : (
                index /
                (
                  values.length -
                  1
                )
              ) *
              width;


        const y =
          height -
          (
            value /
            max
          ) *
          (
            height -
            5
          );


        return [
          x,
          y
        ];

      }
    );


  const path =
    makeSmoothPath(
      points
    );


  const color =
    CW.colors[
      platform
    ] ||
    "#1473e6";


  return `
    <svg
      class="cw-spark"
      viewBox="
        0 0
        ${width}
        ${height}
      "
      preserveAspectRatio="none"
      aria-hidden="true"
    >

      <path
        d="${path}"
        fill="none"
        stroke="${color}"
        stroke-width="2"
        stroke-linecap="round"
      />

    </svg>
  `;
}


