function signalTone(type) {
  const text =
    String(
      type ??
      ""
    )
      .toLowerCase();


  if (
    text.includes(
      "negative"
    ) ||
    text.includes(
      "negativ"
    ) ||
    text.includes(
      "critical"
    ) ||
    text.includes(
      "crít"
    )
  ) {
    return "signal-red";
  }


  if (
    text.includes(
      "warning"
    ) ||
    text.includes(
      "alert"
    ) ||
    text.includes(
      "volume"
    ) ||
    text.includes(
      "spike"
    )
  ) {
    return "signal-orange";
  }


  if (
    text.includes(
      "positive"
    ) ||
    text.includes(
      "positiv"
    )
  ) {
    return "signal-green";
  }


  return "";
}


