                >
                  ${escapeHtml(
                    type
                  )}
                </span>


                <div
                  class="
                    cw-signal-title
                  "
                >
                  ${escapeHtml(
                    truncate(
                      content,
                      115
                    )
                  )}
                </div>


                <div
                  class="
                    cw-signal-meta
                  "
                >

                  ${
                    author
                      ? `${escapeHtml(
                          author
                        )} · `
                      : ""
                  }

                  ${escapeHtml(
                    formatDateTime(
                      date
                    )
                  )}

                  ${
                    row.likes_count !==
                    undefined

                      ? ` · ${formatCompact(
                          row.likes_count
                        )} likes`

                      : ""
                  }

                </div>

              </div>


              ${
                row.post_url

                  ? `
                    <button
                      type="button"
                      class="
                        cw-open-post
                      "
                      data-signal-index="
                        ${index}
                      "
                    >
                      ↗
                    </button>
                  `

                  : ""
              }

            </div>
          `;

        }
      )
      .join("");


  container
    .querySelectorAll(
      "[data-signal-index]"
    )
    .forEach(
      button => {

        button.onclick = () => {

          const index =
            Number(
              button.dataset
                .signalIndex
            );


          openPost(
            visible[index]
          );

        };

      }
    );


  document.getElementById(
    "toggleSignals"
  ).textContent =
    CW.expanded.signals
      ? "Ver menos"
      : "Ver todas";
}


/* =========================================================
   RECENT POSTS
   ========================================================= */

function renderRecentPosts() {
  const rows =
    getRecentPosts()
      .sort(
        (a, b) => {

          const ad =
            safeDate(
              a.published_at
            );


          const bd =
            safeDate(
              b.published_at
            );


          return (
            (
              bd
                ?.getTime() ||
              0
            ) -
            (
              ad
                ?.getTime() ||
              0
            )
          );

        }
      );


  const container =
    document.getElementById(
      "recentPostsList"
    );


  if (!rows.length) {

    container.innerHTML =
      emptyState(
        "↻",
        "Todavía no existe detalle de publicaciones recientes conectado al modelo."
      );

    return;
  }


  const visible =
    CW.expanded.recent

      ? rows.slice(
          0,
          30
        )

      : rows.slice(
          0,
          4
        );


  container.innerHTML =
    visible
      .map(
        (
          row,
          index
        ) => {

          const platform =
            normalizePlatform(
              row.platform
            );


          const content =
            row.content_text ??
            "Publicación sin texto disponible";


          return `
            <div
              class="
                cw-list-item
              "
            >

              <div
                class="
                  cw-thumb
                  platform-${platform}
                "
              >
                ${escapeHtml(
                  platformInitial(
                    platform
                  )
                )}
              </div>


              <div
                class="
                  cw-post-main
                "
              >

                <div
                  class="
                    cw-post-meta
                  "
                >

                  <span>
                    ${escapeHtml(
                      platformLabel(
                        platform
                      )
                    )}
                  </span>

                  <span>
                    ·
                  </span>

                  <span>
                    ${escapeHtml(
                      formatDateTime(
                        row.published_at
                      )
                    )}
                  </span>

                </div>


                <div
                  class="
                    cw-post-title
                  "
                >
                  ${escapeHtml(
                    truncate(
                      content,
                      100
                    )
                  )}
                </div>


                <div
                  class="
                    cw-post-metrics
                  "
                >

                  <span>
                    ♥
                    ${formatCompact(
                      row.likes
                    )}
                  </span>

                  <span>
                    ◯
                    ${formatCompact(
                      row.comments ??
                      row.comments_reported
                    )}
                  </span>

                  <span>
                    ↗
                    ${formatCompact(
                      row.shares
                    )}
                  </span>

                  <span>
                    ◉
                    ${formatCompact(
                      row.views
                    )}
                  </span>

                </div>

              </div>


              ${
                row.post_url

                  ? `
                    <button
                      type="button"
                      class="
                        cw-open-post
                      "
                      data-recent-index="
                        ${index}
                      "
                    >
                      ↗
                    </button>
                  `

                  : ""
              }

            </div>
          `;

        }
      )
      .join("");


  container
    .querySelectorAll(
      "[data-recent-index]"
    )
    .forEach(
      button => {

        button.onclick = () => {

          const index =
            Number(
              button.dataset
                .recentIndex
            );


          openPost(
            visible[index]
          );

        };

      }
    );


  document.getElementById(
    "toggleRecent"
  ).textContent =
    CW.expanded.recent
      ? "Ver menos"
      : "Ver todas";
}


/* =========================================================
   OPEN POST
   ========================================================= */

function openPost(row) {
  if (!row) {
    return;
  }


  appsmith.updateModel({
    selectedPost:
      row
  });


  try {

    appsmith.triggerEvent(
      "onOpenPost",
      {
        post:
          row
      }
    );

  } catch (_) {

    /* Event may not yet be configured */

  }
}


/* =========================================================
   EMPTY STATE
   ========================================================= */

function emptyState(
  symbol,
  text
) {
  return `
    <div class="cw-empty">

      <div
        class="
          cw-empty-inner
        "
      >

        <div
          class="
            cw-empty-symbol
          "
        >
          ${escapeHtml(
            symbol
          )}
        </div>

        ${escapeHtml(
          text
        )}

      </div>

    </div>
  `;
}


/* =========================================================
   BUTTONS
   ========================================================= */

function bindButtons() {
  document.getElementById(
    "refreshButton"
  ).onclick = () => {

    try {

      appsmith.triggerEvent(
        "onRefresh"
      );

    } catch (_) {

      render();

    }

  };


  document.getElementById(
    "toggleTopPosts"
  ).onclick = () => {

    CW.expanded.top =
      !CW.expanded.top;

    renderTopPosts();

  };


  document.getElementById(
    "toggleSignals"
  ).onclick = () => {

    CW.expanded.signals =
      !CW.expanded.signals;

    renderSignals();

  };


  document.getElementById(
    "toggleRecent"
  ).onclick = () => {

    CW.expanded.recent =
      !CW.expanded.recent;

    renderRecentPosts();

  };


  document
    .querySelectorAll(
      "#metricTabs button"
    )
    .forEach(
      button => {

        button.onclick = () => {

          CW.metric =
            button.dataset
              .metric;


          document
            .querySelectorAll(
              "#metricTabs button"
            )
            .forEach(
              item => {

                item.classList.toggle(
                  "active",
                  item ===
                    button
                );

              }
            );


          renderPulseChart();

          renderPlatforms();

        };

      }
    );
}


/* =========================================================
   RENDER
   ========================================================= */

function render() {
  renderControls();

  renderHeader();

  renderSummary();

  renderPulseChart();

  renderPlatforms();

  renderTopPosts();

  renderSignals();

  renderRecentPosts();

  bindButtons();
}


/* =========================================================
   INITIALIZATION
   ========================================================= */

appsmith.onReady(() => {

  CW.model =
    appsmith.model ||
    {};


  CW.filters = {
    ...CW.filters,
    ...(
      CW.model.filters ||
      {}
    )
  };


  render();


  appsmith.onModelChange(
    newModel => {

      CW.model =
        newModel ||
        {};


      if (
        newModel
          ?.filters
      ) {

        CW.filters = {
          ...CW.filters,
          ...newModel.filters
        };

      }


      render();

    }
  );


  appsmith.onUiChange(
    () => {

      clearTimeout(
        CW.resizeTimer
      );


      CW.resizeTimer =
        setTimeout(
          () => {

            renderPulseChart();

            renderPlatforms();

          },
          120
        );

    }
  );

});
